63	interface ViewBuildContext {
64	    api: ExtensionAPI;
65	    geo: Geo;
66	    mapOrGeoModel: GeoModel | MapSeries;
67	    data: SeriesData;
68	    isVisualEncodedByVisualMap: boolean;
69	    isGeo: boolean;
