73	interface GeoStyleableOption {
74	    itemStyle?: GeoItemStyleOption;
75	    lineStyle?: LineStyleOption;
76	}
77	type RegionName = string;
78	
79	/**
80	 * Only these tags enable use `itemStyle` if they are named in SVG.
81	 * Other tags like <text> <tspan> <image> might not suitable for `itemStyle`.
82	 * They will not be considered to be styled until some requirements come.
83	 */
84	const OPTION_STYLE_ENABLED_TAGS: SVGNodeTagLower[] = [
85	    'rect', 'circle', 'line', 'ellipse', 'polygon', 'polyline', 'path'
86	];
87	const OPTION_STYLE_ENABLED_TAG_MAP = zrUtil.createHashMap<number, SVGNodeTagLower>(
88	    OPTION_STYLE_ENABLED_TAGS
89	);
90	const STATE_TRIGGER_TAG_MAP = zrUtil.createHashMap<number, SVGNodeTagLower>(
91	    OPTION_STYLE_ENABLED_TAGS.concat(['g']) as SVGNodeTagLower[]
92	);
93	const LABEL_HOST_MAP = zrUtil.createHashMap<number, SVGNodeTagLower>(
94	    OPTION_STYLE_ENABLED_TAGS.concat(['g']) as SVGNodeTagLower[]
95	);
96	const mapLabelRaw = makeInner<{
97	    ignore: boolean
98	}, ZRText>();
