132	        });
133	        const dataNameMap = zrUtil.createHashMap();
134	        const toAppendNames = [] as string[];
135	
136	        for (let i = 0, len = data.count(); i < len; i++) {
137	            const name = data.getName(i);
138	            dataNameMap.set(name, true);
139	        }
140	
141	        // The region style declared in the original GeoJSON data
142	        // (`feature.properties.echartsStyle`) is collected here, and used as
143	        // the default of the region model in `getRegionModel`. Note that it
144	        // also works for the regions that only exist in the map source but not
145	        // in the `data` specified by users.
146	        const geoJSONRegionStyleMap = this._geoJSONRegionStyleMap =
147	            zrUtil.createHashMap<RegoinOption, string>();
148	        this._regionModelMap = zrUtil.createHashMap<Model<MapDataItemOption>, string>();
149	
150	        const geoSource = geoSourceManager.load(this.getMapType(), this.option.nameMap, this.option.nameProperty);
