    78	                // Remove drawn map
    79	                this._mapDraw && this._mapDraw.remove();
    80	                this._mapDraw = null;
    81	            }
    82	        }
    83	        else {
    84	            const mapDraw = this._mapDraw;
    85	            mapDraw && group.add(mapDraw.group);
