   103	    private _renderSymbols(mapModel: MapSeries, ecModel: GlobalModel, api: ExtensionAPI): void {
   104	        const originalData = mapModel.originalData;
   105	        const group = this.group;
   106	
   107	        originalData.each(originalData.mapDimension('value'), function (value, originalDataIndex) {
   108	            if (isNaN(value as number)) {
   109	                return;
   110	            }
   111	
   112	            const layout = originalData.getItemLayout(originalDataIndex);
   113	
   114	            if (!layout || !layout.point) {
   115	                // Not exists in map
   116	                return;
   117	            }
   118	
   119	            const point = layout.point;
   120	            const offset = layout.offset;
   121	
   122	            const circle = new graphic.Circle({
   123	                style: {
   124	                    // Because the special of map draw.
   125	                    // Which needs statistic of multiple series and draw on one map.
   126	                    // And each series also need a symbol with legend color
   127	                    //
   128	                    // Layout and visual are put one the different data
   129	                    // TODO
   130	                    fill: mapModel.getData().getVisual('style').fill
   131	                },
   132	                shape: {
   133	                    cx: point[0] + offset * 9,
   134	                    cy: point[1],
   135	                    r: 3
   136	                },
   137	                silent: true,
   138	                // Do not overlap the first series, on which labels are displayed.
   139	                z2: 8 + (!offset ? Z2_EMPHASIS_LIFT + 1 : 0)
   140	            });
   141	
   142	            // Only the series that has the first value on the same region is in charge of rendering the label.
   143	            // But consider the case:
   144	            // series: [
   145	            //     {id: 'X', type: 'map', map: 'm', {data: [{name: 'A', value: 11}, {name: 'B', {value: 22}]},
   146	            //     {id: 'Y', type: 'map', map: 'm', {data: [{name: 'A', value: 21}, {name: 'C', {value: 33}]}
   147	            // ]
   148	            // The offset `0` of item `A` is at series `X`, but of item `C` is at series `Y`.
   149	            // For backward compatibility, we follow the rule that render label `A` by the
   150	            // settings on series `X` but render label `C` by the settings on series `Y`.
   151	            if (!offset) {
   152	
   153	                const fullData = mapModel.mainSeries.getData();
   154	                const name = originalData.getName(originalDataIndex);
   155	
   156	                const fullIndex = fullData.indexOfName(name);
   157	
   158	                const itemModel = originalData.getItemModel<MapDataItemOption>(originalDataIndex);
   159	                const labelModel = itemModel.getModel('label');
   160	
   161	                const regionGroup = fullData.getItemGraphicEl(fullIndex);
   162	
   163	                // `getFormattedLabel` needs to use `getData` inside. Here
   164	                // `mapModel.getData()` is shallow cloned from `mainSeries.getData()`.
   165	                // FIXME
   166	                // If this is not the `mainSeries`, the item model (like label formatter)
   167	                // set on original data item will never get. But it has been working
   168	                // like that from the beginning, and this scenario is rarely encountered.
   169	                // So it won't be fixed until we have to.
   170	
   171	                setLabelStyle(circle, getLabelStatesModels(itemModel), {
   172	                    labelFetcher: {
   173	                        getFormattedLabel(idx: number, state: DisplayState) {
   174	                            return mapModel.getFormattedLabel(fullIndex, state);
   175	                        }
   176	                    },
   177	                    defaultText: name
   178	                });
   179	                (circle as ECElement).disableLabelAnimation = true;
   180	                if (!labelModel.get('position')) {
   181	                    circle.setTextConfig({
   182	                        position: 'bottom'
   183	                    });
   184	                }
   185	
   186	                (regionGroup as ECElement).onHoverStateChange = function (toState) {
   187	                    setStatesFlag(circle, toState);
   188	                };
   189	            }
   190	
   191	            group.add(circle);
   192	        });
   193	    }
   194	}
