/*
 * THROWAWAY probe test. Delete after use.
 */

import { EChartsType, registerMap } from '../../../../../src/echarts.all';
import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';
import { getECData } from '../../../../../src/util/innerStore';
import Group from 'zrender/src/graphic/Group';
import MapSeries from '../../../../../src/chart/map/MapSeries';
import GeoModel from '../../../../../src/coord/geo/GeoModel';

function makeFeature(name: string, x0: number) {
    return {
        type: 'Feature',
        properties: { name: name },
        geometry: {
            type: 'Polygon',
            coordinates: [[[x0, 0], [x0, 10], [x0 + 10, 10], [x0 + 10, 0], [x0, 0]]]
        }
    } as any;
}

function getGeoRegionGroup(chart: EChartsType, regionName: string): Group {
    const els = getGraphicElements(chart, 'geo', 0);
    for (let i = 0; i < els.length; i++) {
        const eventData = getECData(els[i]).eventData;
        if (eventData && eventData.name === regionName) {
            return els[i] as Group;
        }
    }
    return null;
}

const SVG_MAP = `<?xml version="1.0" encoding="utf-8"?>
<svg width="100" height="100" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
  <rect name="AAA" x="0" y="0" width="40" height="40" fill="#f00"/>
  <rect name="BBB" x="50" y="50" width="40" height="40" fill="#0f0"/>
</svg>`;

function getSVGEl(chart: EChartsType, mainType: 'geo' | 'series', regionName: string) {
    const els = getGraphicElements(chart, mainType, 0);
    const found: any[] = [];
    for (let i = 0; i < els.length; i++) {
        if ((els[i] as any).name === regionName) {
            found.push(els[i]);
        }
    }
    return found;
}

describe('probe silent', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    it('geo geojson region silent', function () {
        registerMap('probe-1', {
            type: 'FeatureCollection',
            features: [makeFeature('AAA', 0), makeFeature('BBB', 20)]
        } as any);

        chart.setOption({
            geo: { map: 'probe-1', regions: [{ name: 'AAA', silent: true }] }
        });

        const geoModel = getECModel(chart).getComponent('geo', 0) as GeoModel;
        console.log('geo AAA regionModel.get(silent) =', geoModel.getRegionModel('AAA').get('silent' as any));
        console.log('geo BBB regionModel.get(silent) =', geoModel.getRegionModel('BBB').get('silent' as any));

        const gA = getGeoRegionGroup(chart, 'AAA');
        const gB = getGeoRegionGroup(chart, 'BBB');
        console.log('AAA group silent =', gA && gA.silent, 'BBB group silent =', gB && gB.silent);
        console.log('AAA child silent =', gA && gA.childAt(0).silent);
        const textEl = gA && (gA.childAt(0) as any).getTextContent();
        console.log('AAA label silent =', textEl && textEl.silent);

        // now remove silent by merge (regions merge?)
        chart.setOption({
            geo: { map: 'probe-1', regions: [{ name: 'AAA' }] }
        });
        const gA2 = getGeoRegionGroup(chart, 'AAA');
        console.log('after removing silent: AAA group silent =', gA2 && gA2.silent);
        console.log('after removing: regionModel silent =',
            (getECModel(chart).getComponent('geo', 0) as GeoModel).getRegionModel('AAA').get('silent' as any));
    });

    it('series.map data item silent', function () {
        registerMap('probe-2', {
            type: 'FeatureCollection',
            features: [makeFeature('AAA', 0), makeFeature('BBB', 20)]
        } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'probe-2',
                data: [{ name: 'AAA', value: 1, silent: true }, { name: 'BBB', value: 2 }]
            }]
        });

        const seriesModel = getECModel(chart).getSeriesByIndex(0) as MapSeries;
        const data = seriesModel.getData();
        const elA = data.getItemGraphicEl(data.indexOfName('AAA'));
        const elB = data.getItemGraphicEl(data.indexOfName('BBB'));
        console.log('map AAA regionModel silent =', seriesModel.getRegionModel('AAA').get('silent' as any));
        console.log('map BBB regionModel silent =', seriesModel.getRegionModel('BBB').get('silent' as any));
        console.log('map AAA el silent =', elA && elA.silent, 'BBB el silent =', elB && elB.silent);

        // update map data: remove silent
        chart.setOption({
            series: [{
                type: 'map',
                map: 'probe-2',
                data: [{ name: 'AAA', value: 5 }, { name: 'BBB', value: 6 }]
            }]
        });
        const seriesModel2 = getECModel(chart).getSeriesByIndex(0) as MapSeries;
        const data2 = seriesModel2.getData();
        const elA2 = data2.getItemGraphicEl(data2.indexOfName('AAA'));
        console.log('after data update, AAA el silent =', elA2 && elA2.silent);
        console.log('after data update, regionModel silent =', seriesModel2.getRegionModel('AAA').get('silent' as any));
    });

    it('series.map series level silent inheritance', function () {
        registerMap('probe-3', {
            type: 'FeatureCollection',
            features: [makeFeature('AAA', 0), makeFeature('BBB', 20)]
        } as any);
        chart.setOption({
            series: [{
                type: 'map',
                map: 'probe-3',
                silent: true,
                data: [{ name: 'AAA', value: 1 }]
            }]
        });
        const seriesModel = getECModel(chart).getSeriesByIndex(0) as MapSeries;
        console.log('series-level silent inherited by regionModel =',
            seriesModel.getRegionModel('AAA').get('silent' as any));
        const data = seriesModel.getData();
        const elA = data.getItemGraphicEl(data.indexOfName('AAA'));
        console.log('el silent =', elA && elA.silent);
    });

    it('geo svg region silent stale check', function () {
        registerMap('probe-svg', { svg: SVG_MAP } as any);

        chart.setOption({
            geo: { map: 'probe-svg', regions: [{ name: 'AAA', silent: true }] }
        });
        let a = getSVGEl(chart, 'geo', 'AAA');
        let b = getSVGEl(chart, 'geo', 'BBB');
        console.log('SVG AAA els:', a.length, a.map(e => e.silent));
        console.log('SVG BBB els:', b.length, b.map(e => e.silent));

        chart.setOption({
            geo: { map: 'probe-svg', regions: [{ name: 'AAA' }] }
        });
        a = getSVGEl(chart, 'geo', 'AAA');
        console.log('after removing silent, SVG AAA els silent:', a.map(e => e.silent));
    });

    it('series.map svg region silent stale check', function () {
        registerMap('probe-svg2', { svg: SVG_MAP } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'probe-svg2',
                data: [{ name: 'AAA', value: 1, silent: true }, { name: 'BBB', value: 2 }]
            }]
        });
        let a = getSVGEl(chart, 'series', 'AAA');
        console.log('series SVG AAA els silent:', a.map(e => e.silent));

        chart.setOption({
            series: [{
                type: 'map',
                map: 'probe-svg2',
                data: [{ name: 'AAA', value: 3 }, { name: 'BBB', value: 4 }]
            }]
        });
        a = getSVGEl(chart, 'series', 'AAA');
        console.log('AFTER UPDATE series SVG AAA els silent:', a.map(e => e.silent));
    });
});

