/*
 * THROWAWAY probe test 2. Delete after use.
 */

import { EChartsType, registerMap } from '../../../../../src/echarts.all';
import { createChart, getGraphicElements, removeChart } from '../../../core/utHelper';

const SVG_MAP = `<?xml version="1.0" encoding="utf-8"?>
<svg width="100" height="100" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
  <rect name="AAA" x="0" y="0" width="40" height="40" fill="#f00"/>
  <rect name="BBB" x="50" y="50" width="40" height="40" fill="#0f0"/>
</svg>`;

function dumpSilent(chart: EChartsType, mainType: 'geo' | 'series', tag: string) {
    const els = getGraphicElements(chart, mainType, 0);
    const out: string[] = [];
    for (let i = 0; i < els.length; i++) {
        if ((els[i] as any).type === 'rect') {
            out.push('silent=' + els[i].silent);
        }
    }
    console.log('###', tag, out.join(','));
    return out;
}

describe('probe2', function () {
    it('series.map svg stale after data refresh', function () {
        registerMap('probe2-svg', { svg: SVG_MAP } as any);
        const chart = createChart();
        chart.setOption({
            series: [{
                type: 'map', map: 'probe2-svg',
                data: [{ name: 'AAA', value: 1, silent: true }, { name: 'BBB', value: 2 }]
            }]
        });
        dumpSilent(chart, 'series', 'first');
        chart.setOption({
            series: [{
                type: 'map', map: 'probe2-svg',
                data: [{ name: 'AAA', value: 3 }, { name: 'BBB', value: 4 }]
            }]
        });
        const after = dumpSilent(chart, 'series', 'after-data-refresh');
        removeChart(chart);
        // expectation of the requirement: silent removed => false
        expect(after[0]).toEqual('silent=false');
    });

    it('svg graphic pool leak across chart instances', function () {
        registerMap('probe2-svg-b', { svg: SVG_MAP } as any);
        const chart1 = createChart();
        chart1.setOption({
            series: [{
                type: 'map', map: 'probe2-svg-b',
                data: [{ name: 'AAA', value: 1, silent: true }, { name: 'BBB', value: 2 }]
            }]
        });
        dumpSilent(chart1, 'series', 'chart1');
        removeChart(chart1);

        const chart2 = createChart();
        chart2.setOption({
            series: [{
                type: 'map', map: 'probe2-svg-b',
                data: [{ name: 'AAA', value: 1 }, { name: 'BBB', value: 2 }]
            }]
        });
        const after = dumpSilent(chart2, 'series', 'chart2-fresh-no-silent');
        removeChart(chart2);
        expect(after[0]).toEqual('silent=false');
    });
});

